)
$ErrorActionPreference = 'Stop'
$ExactVersion = '4.0.0-alpha.2'
$SourceCommit = 'b0cff8236b8b3746f8028b9d519ed3b0e26096c9'
$CatalogRoot = 'sha256:f68536e7050ca5911948db73e34a1ac5c563c27b8e565fc2cd11f34819c2feff'
$ChannelRoot = '8c031dd420e15ddde5b4e751cb4dcc3c0a2d4bd67956d295918e21165de6abdd'
$ChannelUrl = "https://kungfu.tech/channels/alpha/$ChannelRoot/index.json"
$ChannelSha256 = '8b01d6aab5d71949da2a9ff90f4d05fb725e9338979b52e38454ca653b7ee3ca'
$TrustedKey = 'ed25519-3c473c24ca261745=bNB6syHpgY0RKMHPKUhekyQupwgvtwqQ6qqrUV2ecfQ='
$ReleasePassportRoot = 'sha256:63116c9c3f035025ae0166863cc5ef43dab67dfba153d039a09d428f02dbe2c0'
